SELECT * FROM CLIENTE;

-- INSERTS DE FUNCIONARIOS

SELECT * FROM FUNCIONARIO;

-- INSERTS DE PRODUTOS

SELECT * FROM PRODUTO;

-- VENDAS PAGAS (78 REGISTROS)

-- VENDAS FIADAS (50 REGISTROS - JAN, FEV E MAR)

SELECT * FROM VENDA;

-- 1. LANÇA NO CAIXA TODAS AS ENTRADAS DAS VENDAS PAGAS
SELECT 
    V.ID_VENDA,
    'ENTRADA',
    (V.QUANTIDADE * P.PRECO_VENDA),
    V.DATA_VENDA,
    CONCAT('Venda paga: ', P.NOME)
FROM VENDA V
INNER JOIN PRODUTO P ON V.ID_PRODUTO = P.ID_PRODUTO
WHERE V.STATUS_PAGAMENTO = 'PAGO';

-- 2. LANÇA AS SAÍDAS COM COMPRA DE MERCADORIAS (CUSTO TOTAL DOS PRODUTOS VENDIDOS)
SELECT 
    NULL,
    'SAIDA',
    SUM(V.QUANTIDADE * P.CUSTO),
    '2026-03-01',
    'Reposição de estoque junto aos fornecedores'
FROM VENDA V
INNER JOIN PRODUTO P ON V.ID_PRODUTO = P.ID_PRODUTO;

-- 3. LANÇA AS SAÍDAS COM FOLHA DE PAGAMENTO DOS FUNCIONÁRIOS (JAN, FEV E MAR)
SELECT NULL, 'SAIDA', SUM(SALARIO), '2026-01-31', 'Folha de pagamento Janeiro/2026' FROM FUNCIONARIO
UNION ALL
SELECT NULL, 'SAIDA', SUM(SALARIO), '2026-02-28', 'Folha de pagamento Fevereiro/2026' FROM FUNCIONARIO
UNION ALL
SELECT NULL, 'SAIDA', SUM(SALARIO), '2026-03-31', 'Folha de pagamento Março/2026' FROM FUNCIONARIO;

-- 4. ABATE DO ESTOQUE TODOS OS PRODUTOS VENDIDOS (PAGOS E FIADOS)
SET SQL_SAFE_UPDATES = 0;
UPDATE PRODUTO P
SET P.ESTOQUE = P.ESTOQUE - (
    SELECT COALESCE(SUM(V.QUANTIDADE), 0)
    FROM VENDA V
    WHERE V.ID_PRODUTO = P.ID_PRODUTO
);
SET SQL_SAFE_UPDATES = 1;

SELECT * FROM MOVIMENTACAO_FINANCEIRA;

-- 1. Cadastrando SILAS LOPES como cliente do bar

SELECT * FROM CLIENTE;

DROP TABLE MOVIMENTACAO_FINANCEIRA;
DROP TABLE VENDA;
DROP TABLE PRODUTO;
DROP TABLE FORNECEDOR;
DROP TABLE FUNCIONARIO;
DROP TABLE CLIENTE;

SELECT 'CLIENTE' AS TABELA, COUNT(*) AS TOTAL FROM CLIENTE
UNION ALL SELECT 'FUNCIONARIO', COUNT(*) FROM FUNCIONARIO
UNION ALL SELECT 'FORNECEDOR', COUNT(*) FROM FORNECEDOR
UNION ALL SELECT 'PRODUTO', COUNT(*) FROM PRODUTO
UNION ALL SELECT 'VENDA', COUNT(*) FROM VENDA
UNION ALL SELECT 'MOVIMENTACAO_FINANCEIRA', COUNT(*) FROM MOVIMENTACAO_FINANCEIRA;